const SupplyChainWorkspace=React.lazy(()=>import('./SupplyChainWorkspace').then(m=>({default:m.SupplyChainWorkspace})));
const WorkPackagePage=React.lazy(()=>import('./WorkPackagePage').then(m=>({default:m.WorkPackagePage})));
